'use strict';
const $=id=>document.getElementById(id);
const defaults=()=>({profile:{height:183,chest:92,shoulder:45},candidate:{chest:62,length:64,shoulder:54,sleeve:59},reference:{chest:56,length:70,shoulder:48,sleeve:62},name:'Boxy work jacket',size:'M',category:'Jacket',color:'#344b3b'});
const fields=[['chest','Chest width',30,100],['length','Body length',30,130],['shoulder','Shoulder width',25,85],['sleeve','Sleeve length',10,95]];
let state=defaults(),saved=[],editing='candidate',overlay=true,timer;
try{const data=JSON.parse(localStorage.getItem('fitcheck-v1'));if(data&&data.state&&data.saved){const d=data.state; if(d.profile&&['height','chest','shoulder'].every(k=>Number.isFinite(d.profile[k]))&&['candidate','reference'].every(t=>fields.every(([k,,min,max])=>Number.isFinite(d[t]?.[k])&&d[t][k]>=min&&d[t][k]<=max)))state=d;saved=Array.isArray(data.saved)?data.saved:[];}}catch{}
function notify(message){$('toast').textContent=message;$('toast').classList.remove('hidden');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.add('hidden'),2800)}
function persist(){try{localStorage.setItem('fitcheck-v1',JSON.stringify({state,saved}));$('autosaveStatus').textContent='✓ Changes saved on this device'}catch{$('autosaveStatus').textContent='Storage unavailable — changes last for this visit';} $('savedCount').textContent=saved.length;}
function inputFields(){const container=$('measureFields');container.replaceChildren();fields.forEach(([key,label,min,max])=>{const field=document.createElement('div');field.className='field';const lab=document.createElement('label');lab.htmlFor=key;lab.textContent=label;const wrap=document.createElement('div');wrap.className='measure';const input=document.createElement('input');Object.assign(input,{id:key,type:'number',min,max,step:0.5,value:state[editing][key],required:true});const unit=document.createElement('span');unit.textContent='cm';input.addEventListener('input',()=>{if(!input.validity.valid)return;state[editing][key]=Number(input.value);render();persist()});input.addEventListener('blur',()=>{if(!input.validity.valid){input.value=state[editing][key];notify('Enter a measurement between '+min+' and '+max+' cm.')}});wrap.append(input,unit);field.append(lab,wrap);container.append(field)});$('candidateTab').classList.toggle('active',editing==='candidate');$('referenceTab').classList.toggle('active',editing==='reference');$('measurementHelp').textContent=editing==='candidate'?'The piece you’re thinking of buying.':'A piece you own and like. Measure it flat using the same method.';}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const fmt=n=>`${n>0?'+':''}${Math.round(n*10)/10}`;
function forecast(s){const c=s.candidate,r=s.reference;let title=(c.chest-r.chest>2?'Roomier':c.chest-r.chest< -2?'Closer fitting':'Similar width')+(c.length-r.length< -3?' & shorter.':c.length-r.length>3?' & longer.':'.');if(c.chest-r.chest>3&&c.length-r.length< -3)title='Boxier & shorter.';return title;}
function garmentPath(g){const shoulder=g.shoulder/2, chest=g.chest/2;const sx=shoulder,sy=104;const sleeve=g.sleeve,ax=.38*sleeve,ay=.925*sleeve;const cuff=6;return `M ${210-10} 100 L ${210-sx} ${sy} L ${210-sx-ax-cuff} ${sy+ay} L ${210-sx-ax+cuff} ${sy+ay+5} L ${210-chest} 132 L ${210-chest} ${100+g.length} Q 210 ${104+g.length} ${210+chest} ${100+g.length} L ${210+chest} 132 L ${210+sx+ax-cuff} ${sy+ay+5} L ${210+sx+ax+cuff} ${sy+ay} L ${210+sx} ${sy} L 220 100 Q 210 112 200 100 Z`;}
function svg(){// 1.72 drawing units per centimeter, with a fixed high-shoulder anchor.
const p=state.profile,c=state.candidate,r=state.reference;const scale=1.72, shoulder=p.shoulder/2,chest=p.chest/Math.PI/2,top=100,foot=top+p.height*.815,screenFoot=top+(foot-top)*scale;const body=`M ${210-shoulder} 104 Q ${210-chest-3} 125 ${210-chest} 145 L 192 164 L 190 ${164+(foot-164)*.5} L 189 ${foot} L 204 ${foot} L 210 176 L 216 ${foot} L 231 ${foot} L 230 ${164+(foot-164)*.5} L 228 164 L ${210+chest} 145 Q ${210+chest+3} 125 ${210+shoulder} 104 L 220 100 L 220 90 L 200 90 L 200 100 Z`;const dim=(r.length-c.length)*scale;return `<defs><filter id="shadow"><feGaussianBlur stdDeviation="5"/></filter></defs><ellipse cx="210" cy="${screenFoot+5}" rx="55" ry="6" fill="#71815d" opacity=".12" filter="url(#shadow)"/><g transform="translate(${210*(1-scale)} ${100*(1-scale)}) scale(${scale})"><ellipse cx="210" cy="78" rx="11.5" ry="16" fill="#c5c9b9"/><path d="${body}" fill="#c5c9b9"/><path d="M ${210-shoulder} 109 L ${210-shoulder-14} 142 L ${210-shoulder-22} 169 M ${210+shoulder} 109 L ${210+shoulder+14} 142 L ${210+shoulder+22} 169" fill="none" stroke="#c5c9b9" stroke-width="10" stroke-linecap="round"/><path d="M 192 164 Q 210 169 228 164 M 210 167 L 210 176" stroke="#aeb5a0" fill="none"/><path d="${garmentPath(c)}" fill="${state.color}" stroke="#17271d" stroke-opacity=".18" stroke-width=".8"/><path d="M 200 100 Q 210 120 220 100" stroke="#ffffff38" fill="none" stroke-width="1.2"/>${state.category==='Jacket'||state.category==='Shirt'?`<path d="M 210 111 V ${100+c.length}" stroke="#ffffff26" stroke-width=".7"/><path d="M ${210-c.chest/2+6} 140 L ${210-c.chest/2+18} 140 V 151 H ${210-c.chest/2+6} Z" fill="#ffffff09" stroke="#ffffff24" stroke-width=".5"/>`:''}${overlay?`<path d="${garmentPath(r)}" fill="none" stroke="#9baa86" stroke-width="1" stroke-dasharray="3 3"/>`:''}</g><path d="M 79 67 H 86 M 82 67 V ${screenFoot} M 79 ${screenFoot} H 86" fill="none" stroke="#adb99d" stroke-width=".7" stroke-dasharray="2 3"/>${overlay&&Math.abs(dim)>4?`<path d="M 324 ${100+c.length*scale} h 6 M 327 ${100+c.length*scale} V ${100+r.length*scale} M 324 ${100+r.length*scale} h 6" stroke="#788969" fill="none"/><text x="337" y="${103+(c.length+r.length)/2*scale}" fill="#6e7b61" font-family="Arial" font-size="9">${fmt(c.length-r.length)} cm</text>`:''}`;}
function render(){const c=state.candidate,r=state.reference,p=state.profile;$('fitSvg').innerHTML=svg();$('heightTag').textContent=p.height+' CM';$('profileSummary').textContent=p.height+' cm ↗';$('fitTitle').textContent=forecast(state);const ease=2*c.chest-p.chest;let fit=ease<0?'The chest is smaller than your body circumference; a non-stretch piece may not close comfortably.':ease<8?'Chest ease is limited, suggesting a close fit before accounting for fabric and layering.':ease>24?'The chest has generous room for a relaxed shape or layering.':'The chest allows some room over your body, before accounting for fabric and layering.';$('fitSummary').textContent=fit;const reach=(c.shoulder-r.shoulder)/2+c.sleeve-r.sleeve;const rows=[['Chest width',c.chest-r.chest,`Pit-to-pit ${c.chest} vs ${r.chest} cm. ${Math.abs(2*(c.chest-r.chest))} cm ${c.chest>=r.chest?'more':'less'} around the garment.`],['Body length',c.length-r.length,Math.abs(c.length-r.length)<1?'A similar hem position to your reference.':`The hem should sit about ${Math.abs(c.length-r.length)} cm ${c.length<r.length?'higher':'lower'} with the same measurement method.`],['Shoulders',c.shoulder-r.shoulder,`The shoulder seam moves about ${Math.abs((c.shoulder-r.shoulder)/2)} cm ${c.shoulder>=r.shoulder?'outward':'inward'} on each side.`],['Sleeve reach',reach,`Shoulder half-width + sleeve: ${Math.abs(Math.round(reach*10)/10)} cm ${reach>=0?'more':'less'} reach. Seam placement changes the result.`]];$('resultRows').innerHTML=rows.map(([label,d,desc])=>`<div class="result-row"><header><span>${label}</span><span class="delta">${fmt(d)} cm</span></header><div class="bar"><i style="left:${d<0?50-Math.min(45,Math.abs(d)*3):50}%;width:${Math.min(45,Math.abs(d)*3)}%"></i></div><p>${desc}</p></div>`).join('');$('legendSwatch').style.background=state.color;document.querySelectorAll('[data-color]').forEach(b=>{const selected=b.dataset.color===state.color;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',selected)});}
function sync(){ $('garmentName').value=state.name;$('size').value=state.size;$('category').value=state.category;inputFields();render();$('savedCount').textContent=saved.length;}
$('candidateTab').onclick=()=>{editing='candidate';inputFields()};$('referenceTab').onclick=()=>{editing='reference';inputFields()};['garmentName','size','category'].forEach((id,i)=>$(id).addEventListener('input',()=>{state[['name','size','category'][i]]=$(id).value;render();persist()}));
$('overlayBtn').onclick=()=>setOverlay(true);$('pieceOnlyBtn').onclick=()=>setOverlay(false);function setOverlay(on){overlay=on;['overlayBtn','pieceOnlyBtn'].forEach((id,i)=>{const active=i===0?on:!on;$(id).classList.toggle('active',active);$(id).setAttribute('aria-pressed',active)});render()}
document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{state.color=b.dataset.color;render();persist()});
function openProfile(){ $('bodyHeight').value=state.profile.height;$('bodyChest').value=state.profile.chest;$('bodyShoulder').value=state.profile.shoulder;$('profileDialog').showModal();} $('profileBtn').onclick=openProfile;$('editProfile').onclick=openProfile;$('cancelProfile').onclick=()=>$('profileDialog').close();$('profileForm').onsubmit=e=>{e.preventDefault();state.profile={height:Number($('bodyHeight').value),chest:Number($('bodyChest').value),shoulder:Number($('bodyShoulder').value)};$('profileDialog').close();render();persist();notify('Fit profile updated')};
$('resetBtn').onclick=()=>{state=defaults();editing='candidate';setOverlay(true);sync();persist();notify('Demo measurements restored. Saved comparisons kept.')};
$('saveBtn').onclick=()=>{if(!state.name.trim()){notify('Give this piece a name first.');$('garmentName').focus();return;}saved.unshift({id:globalThis.crypto?.randomUUID?.() || Date.now().toString(36)+Math.random().toString(36).slice(2),state:JSON.parse(JSON.stringify(state)),date:new Date().toISOString()});persist();notify('Comparison saved to your wardrobe')};
function showRoom(){ $('room').classList.remove('hidden');$('wardrobe').classList.add('hidden');$('roomTab').classList.add('active');$('wardrobeTab').classList.remove('active')};function wardrobe(){ $('room').classList.add('hidden');$('wardrobe').classList.remove('hidden');$('wardrobeTab').classList.add('active');$('roomTab').classList.remove('active');const grid=$('wardrobeGrid');grid.replaceChildren();if(!saved.length){grid.innerHTML='<div class="empty"><h2>Your next good fit starts here.</h2><p>Save a comparison from the fitting room to build your archive.</p><button class="secondary" id="emptyRoom">Go to fitting room ↗</button></div>';$('emptyRoom').onclick=showRoom;return;}saved.forEach(item=>{const s=item.state;const card=document.createElement('article');card.className='panel wardrobe-card';card.innerHTML=`<div class="eyebrow">${escapeHtml(s.category)} / ${escapeHtml(s.size)}</div><h3>${escapeHtml(s.name)}</h3><div class="tag" style="display:inline-block">${escapeHtml(forecast(s))}</div><p>Chest ${s.candidate.chest} · Length ${s.candidate.length}<br>Shoulder ${s.candidate.shoulder} · Sleeve ${s.candidate.sleeve} cm</p><div class="dialog-actions"><button class="secondary" data-action="open">Open comparison ↗</button><button class="secondary" data-action="delete" aria-label="Delete saved comparison">Delete</button></div>`;card.querySelector('[data-action="open"]').onclick=()=>{state=JSON.parse(JSON.stringify(s));editing='candidate';sync();persist();showRoom()};card.querySelector('[data-action="delete"]').onclick=()=>{saved=saved.filter(x=>x.id!==item.id);persist();wardrobe();notify('Comparison deleted')};grid.append(card)});}
$('roomTab').onclick=showRoom;$('wardrobeTab').onclick=wardrobe;$('newComparison').onclick=showRoom;sync();
